const DIRS=[[0,1],[1,0],[0,-1],[-1,0]];

function gridSimulation(grid, moves) {
  const rows=grid.length, cols=grid[0].length;
  let r=0,c=0,dirIdx=0;
  for (const move of moves) {
    if (move==='R') dirIdx=(dirIdx+1)%4;
    else if (move==='L') dirIdx=(dirIdx+3)%4;
    else if (move==='F') {
      const [dr,dc]=DIRS[dirIdx];
      const nr=r+dr, nc=c+dc;
      if (nr>=0 && nr<rows && nc>=0 && nc<cols) { r=nr; c=nc; }
    }
  }
  return [r,c,dirIdx];
}

function simulateWithCycle(initialState, k, stepFn, serialize) {
  const seen=new Map();
  let state=initialState;
  for (let i=0;i<k;i++) {
    const key=serialize(state);
    if (seen.has(key)) {
      const cycleStart=seen.get(key);
      const cycleLen=i-cycleStart;
      const remaining=(k-cycleStart)%cycleLen;
      state=initialState;
      for (let j=0;j<cycleStart+remaining;j++) state=stepFn(state);
      return state;
    }
    seen.set(key,i);
    state=stepFn(state);
  }
  return state;
}
